import unittest
from shipping import shipping_label
import random
import string

class TestShippingLabelFuzz(unittest.TestCase):
    def test_fuzz(self):
        rng = random.Random(1234)
        for _ in range(500):
            weight = rng.randint(-100, 200)
            label = shipping_label(weight)
            if weight > 100:
                self.assertEqual(label, 'freight')
            elif weight >= 10:
                self.assertEqual(label, 'heavy')
            else:
                self.assertEqual(label, 'light')
if __name__ == '__main__':
    unittest.main()

